/**
 * assets.js — sprite cắt từ ảnh tham chiếu neon-drift-404.png
 * (data URL WebP). Xe đã xoay sẵn cho mũi hướng +x; nhà neon là mảng
 * texture ốp vào decor; asphalt dùng làm pattern mặt đường.
 */

export const ASSETS = {
  car:
    "data:image/webp;base64,",
  traffic:
    "data:image/webp;base64,",
  pickup:
    "data:image/webp;base64,",
  pillarL:
    "data:image/webp;base64,",
  pillarR:
    "data:image/webp;base64,",
  banner:
    "data:image/webp;base64,",
  fence:
    "data:image/webp;base64,",
  bldgA:
    "data:image/webp;base64,",
  bldgB:
    "data:image/webp;base64,",
  bldgC:
    "data:image/webp;base64,",
  road:
    "data:image/webp;base64,",
};

/** Tạo và decode Image cho toàn bộ ASSETS; trả về map name → HTMLImageElement. */
export function loadImages() {
  const out = {};
  for (const [k, v] of Object.entries(ASSETS)) {
    const im = new Image();
    im.decoding = "async";
    im.src = v;
    out[k] = im;
  }
  return out;
}

/** Ảnh đã sẵn sàng vẽ chưa (decode xong, hợp lệ). */
export const ready = (im) => !!(im && im.complete && im.naturalWidth > 0);
